#include "TestSupport.h"
#include "DspStageRuntime.h"
#include <cmath>
int main(){auto s=session(1);StageBusWin32 source,consumer;DspStageRuntime dsp;CenterSettings settings;settings.values[0]=0;std::string error;CHECK(dsp.prepareCenter(CENTER_MODULE_ROOT,settings,error));CHECK(source.create(s,error));CHECK(dsp.attach(s,error));CHECK(consumer.open(dsp.outputSession(),error));Planes<10> in;Planes<11> out;in.data[0].fill(1.5);in.data[1].fill(1.5);for(unsigned c=2;c<10;c++)for(unsigned i=0;i<1024;i++){uint64_t u=(i%4==0)?0x8000000000000000ULL:(i%4==1)?0x7ff8000000000000ULL+i:(i%4==2)?0x7ff0000000000000ULL:0x3ff0000000000000ULL+c;std::memcpy(&in.data[c][i],&u,8);}auto req=request(s,1);req.program.music_program_active=0;req.program.program=1;req.program.required_inputs=2;req.program.hardware_armed=1;CHECK(consumer.trySendRequest(req)==StageBusIoResult::Ok);CHECK(dsp.step(qpc())!=DspStepResult::Fault);StageBusFrameRequest upstream{};CHECK(source.tryReceiveRequest(upstream)==StageBusIoResult::Ok);CHECK(upstream.program.required_inputs==3 && upstream.program.music_program_active==1 && !upstream.program.hardware_armed);auto b=header(upstream);CHECK(source.tryPublish(b,in.in.data())==StageBusIoResult::Ok);CHECK(dsp.step(qpc())==DspStepResult::Published);StageBusBlockHeader result{};CHECK(consumer.tryConsume(result,out.out.data())==StageBusIoResult::Ok);CHECK(!std::memcmp(&b,&result,sizeof(b)));for(unsigned c=0;c<10;c++)CHECK(!std::memcmp(in.in[c],out.in[c<2?c:c+1],8192));for(auto value:out.data[2])CHECK(value==1.5);CHECK(dsp.diagnostics().signal.outputMask&4);
// A new bus UUID resets Center's lookahead history; old programme C cannot leak.
consumer.close();dsp.stop();source.close();settings.values[13]=50;CHECK(dsp.applyCenter(settings,2));s=session(1);CHECK(source.create(s,error));CHECK(dsp.attach(s,error));CHECK(consumer.open(dsp.outputSession(),error));in.data[0].fill(1);in.data[1].fill(1);
auto cycle=[&](uint64_t sequence){auto r=request(s,sequence);if(consumer.trySendRequest(r)!=StageBusIoResult::Ok)return false;if(dsp.step(qpc())==DspStepResult::Fault)return false;StageBusFrameRequest up{};if(source.tryReceiveRequest(up)!=StageBusIoResult::Ok)return false;auto h=header(up);if(source.tryPublish(h,in.in.data())!=StageBusIoResult::Ok)return false;if(dsp.step(qpc())!=DspStepResult::Published)return false;return consumer.tryConsume(h,out.out.data())==StageBusIoResult::Ok;};
for(uint64_t sequence=1;sequence<=12;sequence++)CHECK(cycle(sequence));CHECK(out.data[2][1023]==1);
consumer.close();dsp.stop();source.close();s=session(1);CHECK(source.create(s,error));CHECK(dsp.attach(s,error));CHECK(!dsp.diagnostics().center.latencyValid);CHECK(consumer.open(dsp.outputSession(),error));in.data[0].fill(0);in.data[1].fill(0);CHECK(cycle(1));for(auto value:out.data[2])CHECK(bits(value)==0);CHECK(dsp.diagnostics().center.telemetry.latency_samples==9600);
std::cout<<"PASS Centre C-only, bitwise LR and all Cinema including NaN/signed-zero payloads; original header identity and neutral upstream programme independent of downstream selection\n";}
